class _FileIOCopy:
    """A real, file-descriptor-backed byte stream that copies everything
    written to it into another stream.

    Unlike :class:`BytesIOCopy`, this is backed by an actual OS-level file,
    so ``fileno()`` works. This allows code under test to pass ``sys.stdout``
    or ``sys.stderr`` to APIs such as :func:`subprocess.run` that require a
    real file descriptor.

    .. versionadded:: 8.3
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file = tempfile.TemporaryFile()
        self.copy_to = copy_to

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def fileno(self) -> int:
        return self._file.fileno()

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)


